p="shared/case-helpers.js"
s=open(p).read()
old='''// ------------------------------------------------------------------- waits --
async function settle(page) {
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(250);
}'''
new='''// ------------------------------------------------------------------- waits --
// "Settled" is a state the page reaches, not a duration to sit out: the fonts
// are in, every image has decoded, and the DOM has stopped changing across
// consecutive animation frames. A page that never goes quiet — something
// re-rendering on an interval — is captured at the frame cap rather than held
// forever, which is the old blind wait's behaviour and its worst case.
const QUIET_FRAMES = 2;
const MAX_FRAMES = 30;

async function settle(page) {
  if (hasPausedClock(page)) {
    // The frames belong to the case, which winds them deliberately — there is
    // nothing here to wait out but the loading the network still owes.
    await page.evaluate(async () => {
      await document.fonts.ready;
      const pending = [...document.images].filter((i) => !i.complete);
      await Promise.all(pending.map((i) => i.decode().catch(() => {})));
    });
    return;
  }
  await page.evaluate(
    async ({ quietFrames, maxFrames }) => {
      await document.fonts.ready;
      let dirty = false;
      const observer = new MutationObserver(() => {
        dirty = true;
      });
      observer.observe(document.documentElement, {
        subtree: true,
        childList: true,
        attributes: true,
        characterData: true,
      });
      try {
        let quiet = 0;
        for (let i = 0; i < maxFrames && quiet < quietFrames; i++) {
          // An image still loading will change the layout when it lands, so it
          // is decoded first and the quiet count starts over.
          const pending = [...document.images].filter((img) => !img.complete);
          if (pending.length) {
            await Promise.all(pending.map((img) => img.decode().catch(() => {})));
            quiet = 0;
            continue;
          }
          dirty = false;
          await new Promise((resolve) => requestAnimationFrame(() => resolve()));
          quiet = dirty ? 0 : quiet + 1;
        }
      } finally {
        observer.disconnect();
      }
    },
    { quietFrames: QUIET_FRAMES, maxFrames: MAX_FRAMES }
  );
}'''
assert old in s
