s=s.replace('''const { REFERENCE_NOW_UTC_MS } = require("./reference-now");''','''const { REFERENCE_NOW_UTC_MS } = require("./reference-now");
const { hasPausedClock } = require("./harness/browser");''')
open(p,"w").write(s)
print("ok")
PY
