// How many frames does each page actually need to go quiet, and what mutates?
const path=require("node:path");
const R="/home/user/EdFringeNow/product/requirements";
const {newPage,ORIGIN,closeBrowser}=require(path.join(R,"shared/harness/browser"));
const {loadCases}=require(path.join(R,"shared/cases"));
const H=require(path.join(R,"shared/case-helpers"));
const names=["jerusalem-grid.18.4","jerusalem-chrome.18.1"];
const cases=loadCases().filter(c=>c.kind==="screen");
(async()=>{
 for(const nm of names){
  const tc=cases.find(c=>c.name===nm);
  const {page,context}=await newPage({viewport:tc.viewport,localStorage:tc.localStorage,geolocation:tc.geolocation,timezone:tc.timezone,colorScheme:tc.colorScheme});
  await page.goto(`${ORIGIN}${tc.page||"/"}`,{waitUntil:"load"});
  if(tc.ready) await tc.ready(page); else await H.jerusalemReady(page);
  const r=await page.evaluate(async()=>{
    const log=[];let dirty=false;let last=null;
    const obs=new MutationObserver(ms=>{dirty=true; const m=ms[0]; last=m.type+" on "+(m.target.nodeName||"?")+"."+((m.target.className||"")+"").slice(0,40)+(m.type==="attributes"?" attr="+m.attributeName:"");});
    obs.observe(document.documentElement,{subtree:true,childList:true,attributes:true,characterData:true});
    let quiet=0;
    for(let i=0;i<30 && quiet<2;i++){
      dirty=false;
      await new Promise(res=>requestAnimationFrame(()=>res()));
      if(dirty){quiet=0;log.push(i+": "+last);} else quiet++;
    }
    obs.disconnect();
    return {frames:log.length?log.length:0, sample:log.slice(0,6)};
  });
  console.log(nm, JSON.stringify(r));
  await context.close();
 }
 await closeBrowser();
})();
EOF
node $S/quiesce.js > $S/quiesce.txt 2>&1; echo "EXIT:$?"; cat $S/quiesce.txt

