// Is a crop of ONE fullPage raster pixel-identical to Chromium's own clip?
const path=require("node:path");
const R="/home/user/EdFringeNow/product/requirements";
const {newPage,ORIGIN,closeBrowser}=require(path.join(R,"shared/harness/browser"));
const {loadCases}=require(path.join(R,"shared/cases"));
const H=require(path.join(R,"shared/case-helpers"));
const {decode,encode}=require(path.join(R,"shared/png"));
function crop(img,x,y,w,h){
  const out=Buffer.alloc(w*h*4);
  for(let r=0;r<h;r++) img.data.copy(out,r*w*4,((y+r)*img.width+x)*4,((y+r)*img.width+x+w)*4);
  return {width:w,height:h,data:out};
}
(async()=>{
  const tc=loadCases().find(c=>c.name==="jerusalem-grid.18.4");
  const {page,context}=await newPage({viewport:tc.viewport,localStorage:tc.localStorage,geolocation:tc.geolocation,timezone:tc.timezone,colorScheme:tc.colorScheme});
  await page.goto(`${ORIGIN}${tc.page||"/"}`,{waitUntil:"load"});
  if(tc.ready) await tc.ready(page); else await H.jerusalemReady(page);
  await H.scrollToTop(page);
  const rects=[];
  for(const sel of [".sch-show","#lanes .lane","#railBand"]) { try{ rects.push(await page.locator(sel).first().boundingBox()); }catch{} }
  let t=Date.now();
  const clips=[]; for(const r of rects) clips.push(await page.screenshot({clip:{x:Math.floor(r.x),y:Math.floor(r.y),width:Math.ceil(r.width),height:Math.ceil(r.height)},fullPage:true,animations:"disabled"}));
  const tClips=Date.now()-t;
  t=Date.now();
  const full=decode(await page.screenshot({fullPage:true,animations:"disabled"}));
  const crops=rects.map(r=>encode(crop(full,Math.floor(r.x),Math.floor(r.y),Math.ceil(r.width),Math.ceil(r.height))));
  const tCrop=Date.now()-t;
  console.log("n_clips",rects.length,"chromium_clips_ms",tClips,"one_raster+crop_ms",tCrop);
  rects.forEach((r,i)=>{
