const path=require("node:path");
const R="/home/user/EdFringeNow/product/requirements";
const {newPage,ORIGIN,closeBrowser}=require(path.join(R,"shared/harness/browser"));
const H=require(path.join(R,"shared/case-helpers"));
const CARD='.show-item:has-text("A Good Time Charlie")';
(async()=>{
  const {page,context}=await newPage({localStorage:H.nowStorage()});
  await page.goto(`${ORIGIN}/`,{waitUntil:"load"});
  await H.nowReady(page); await H.scrollToTop(page);
  await page.click(CARD); await page.waitForSelector(".show-item--leg"); await H.settle(page);
  const log=await page.evaluate(async()=>{
    const out=[]; const t0=performance.now();
    const obs=new MutationObserver(ms=>{for(const m of ms) out.push(Math.round(performance.now()-t0)+"ms "+m.type+" <"+m.target.nodeName+" class="+((m.target.className||"")+"").slice(0,30)+">"+(m.type==="attributes"?" @"+m.attributeName+"="+(m.target.getAttribute?m.target.getAttribute(m.attributeName):""):""));});
    obs.observe(document.documentElement,{subtree:true,childList:true,attributes:true,characterData:true});
    await new Promise(r=>setTimeout(r,700));
    obs.disconnect(); return out.slice(0,25);
  });
