// Stability of every screen case: R renders each, pooled, counting matches.
const path=require("node:path");
const R="/home/user/EdFringeNow/product/requirements";
const {closeBrowser,launchBrowser}=require(path.join(R,"shared/harness/browser"));
const {renderScreenCase}=require(path.join(R,"shared/render-case"));
const {loadCases,goldenPath}=require(path.join(R,"shared/cases"));
const {compareToGolden}=require(path.join(R,"shared/compare"));
const REPS=Number(process.env.REPS||3), POOL=Number(process.env.POOL||8);
(async()=>{
  await launchBrowser();
  const cases=loadCases().filter(c=>c.kind==="screen");
  const jobs=[]; for(const c of cases) for(let i=0;i<REPS;i++) jobs.push(c);
  const score=new Map(cases.map(c=>[c.name,0]));
  const t0=Date.now();
  await Promise.all(Array.from({length:POOL},async()=>{
    for(;;){ const tc=jobs.shift(); if(!tc) return;
      try{ const png=await renderScreenCase(tc); if(compareToGolden(tc.name,png,goldenPath(tc)).ok) score.set(tc.name,score.get(tc.name)+1); }catch(e){}
    }
  }));
  const bad=[...score].filter(([,v])=>v<REPS);
  console.log(`${cases.length} cases x${REPS} in ${((Date.now()-t0)/1000).toFixed(0)}s — unstable: ${bad.length}`);
  for(const [n,v] of bad) console.log(`  ${v}/${REPS} ${n}`);
  await closeBrowser();
})();
EOF
