1	// The pixel comparator: a rendered actual against its committed golden, at
2	// ZERO tolerated difference. The harness pins every nondeterministic input, so
3	// any differing pixel is a real change to the product's surface — if rendering
4	// ever proves unstable, the fix is more determinism (fonts, clock, fakes),
5	// never a threshold.
6	"use strict";
7	
8	const fs = require("node:fs");
9	const { decode, encode, isAnimated } = require("./png");
10	const { artifactPath } = require("./artifacts-dir");
11	
12	/**
13	 * Compare a freshly rendered PNG buffer to the committed golden at
14	 * `expectedPath`. On any difference, writes `<name>.actual.png` and (when
15	 * dimensions allow) `<name>.diff.png` into the artifacts dir and returns a
16	 * failure description; returns { ok: true } on an exact match.
17	 */
18	// The differing pixels' bounding box, in words: where in the image it sits and
19	// how big a share of it moved, so a red lane reads without its diff image.
20	function describeRegion({ x0, y0, x1, y1 }, width, height) {
21	  const w = x1 - x0 + 1;
22	  const h = y1 - y0 + 1;
23	  const band = y0 < height / 3 ? "top" : y0 < (2 * height) / 3 ? "middle" : "bottom";
24	  return `all of it inside ${w}x${h} at (${x0},${y0}) — the ${band} of a ${width}x${height} image`;
25	}
26	
27	function compareToGolden(name, actualBuffer, expectedPath) {
28	  if (!fs.existsSync(expectedPath)) {
29	    const actualPath = artifactPath(`${name}.actual.png`);
30	    fs.writeFileSync(actualPath, actualBuffer);
31	    return {
32	      ok: false,
33	      reason: `no committed golden at ${expectedPath} — proposed render written to ${actualPath}; ` +
34	        "a new golden is owner-approved via the refresh lane, never silently adopted",
35	    };
36	  }
37	
38	  const expectedBuffer = fs.readFileSync(expectedPath);
39	  if (expectedBuffer.equals(actualBuffer)) return { ok: true };
40	
41	  // An animated golden is compared on byte-identity alone: the pixel differ
42	  // reads a single still image, so diffing one frame of a flow would describe
43	  // the wrong thing. Both files are written for the owner to play side by side.
44	  if (isAnimated(actualBuffer) || isAnimated(expectedBuffer)) {
45	    const actualPath = artifactPath(`${name}.actual.png`);
46	    fs.writeFileSync(actualPath, actualBuffer);
47	    return {
48	      ok: false,
49	      reason:
50	        `${name}: the animated golden changed (${expectedBuffer.length} bytes committed, ` +
51	        `${actualBuffer.length} rendered). Play ${actualPath} against ${expectedPath}. ` +
52	        "If the change is intended, the re-baselining procedure applies: surface both to " +
53	        "the owner and refresh only on approval.",
54	    };
55	  }
56	
57	  // Byte-different: decode and diff pixel-by-pixel so the artifact shows where.
58	  const actual = decode(actualBuffer);
59	  const expected = decode(expectedBuffer);
60	  const actualPath = artifactPath(`${name}.actual.png`);
61	  fs.writeFileSync(actualPath, actualBuffer);
62	
63	  if (actual.width !== expected.width || actual.height !== expected.height) {
64	    return {
65	      ok: false,
66	      reason:
67	        `${name}: size changed — expected ${expected.width}x${expected.height}, ` +
68	        `got ${actual.width}x${actual.height}. Actual at ${actualPath}.`,
69	    };
70	  }
71	
72	  // Identical pixels encoded differently still count as a pass — the assertion
73	  // is about the rendered surface, not the encoder's filter choices.
74	  const { width, height } = actual;
75	  const diff = Buffer.alloc(width * height * 4);
76	  let diffPixels = 0;
77	  // Where the difference is, not just how much of it there is. The failure
78	  // artifacts are uploaded to a host a session cannot reach, so for anyone
79	  // reading this in a CI log the bounding box IS the diff image.
80	  const bounds = { x0: Infinity, y0: Infinity, x1: -1, y1: -1 };
81	  for (let i = 0; i < width * height; i++) {
82	    const o = i * 4;
83	    const same =
84	      actual.rgba[o] === expected.rgba[o] &&
85	      actual.rgba[o + 1] === expected.rgba[o + 1] &&
86	      actual.rgba[o + 2] === expected.rgba[o + 2] &&
87	      actual.rgba[o + 3] === expected.rgba[o + 3];
88	    if (same) {
89	      // Faded expected pixel as context.
90	      diff[o] = 255 - ((255 - expected.rgba[o]) >> 2);
91	      diff[o + 1] = 255 - ((255 - expected.rgba[o + 1]) >> 2);
92	      diff[o + 2] = 255 - ((255 - expected.rgba[o + 2]) >> 2);
93	      diff[o + 3] = 255;
94	    } else {
95	      diffPixels++;
96	      const x = i % width;
97	      const y = (i - x) / width;
98	      if (x < bounds.x0) bounds.x0 = x;
99	      if (y < bounds.y0) bounds.y0 = y;
100	      if (x > bounds.x1) bounds.x1 = x;
101	      if (y > bounds.y1) bounds.y1 = y;
102	      diff[o] = 255;
103	      diff[o + 1] = 0;
104	      diff[o + 2] = 0;
105	      diff[o + 3] = 255;
106	    }
107	  }
108	  if (diffPixels === 0) return { ok: true };
109	
110	  const diffPath = artifactPath(`${name}.diff.png`);
111	  fs.writeFileSync(diffPath, encode({ width, height, rgba: diff }));
112	  return {
113	    ok: false,
114	    reason:
115	      `${name}: ${diffPixels} of ${width * height} pixels differ ` +
116	      `(${((diffPixels / (width * height)) * 100).toFixed(2)}%), ${describeRegion(bounds, width, height)}. ` +
117	      `See ${actualPath} and ${diffPath}. If the change is intended, the re-baselining ` +
118	      "procedure applies: surface actual/expected/diff to the owner and refresh only on approval.",
119	  };
120	}
121	
122	module.exports = { compareToGolden };

