async function run(mode, rate){
  const {page,context}=await newPage({localStorage:{...H.nowStorage(),...H.nowSettings({genres:[]})}});
  const cdp=await context.newCDPSession(page);
  await cdp.send("Emulation.setCPUThrottlingRate",{rate});
