const {compareToGolden}=require(path.join(R,"shared/compare"));
const name=process.argv[2], total=Number(process.argv[3]||12), pool=Number(process.argv[4]||8);
(async()=>{
  await launchBrowser();
  const tc=loadCases().find(c=>c.name===name);
  let ok=0; const fails=[];
  const q=Array.from({length:total},(_,i)=>i);
  await Promise.all(Array.from({length:pool},async()=>{
    for(;;){ if(!q.length) return; q.shift();
      try{ const png=await renderScreenCase(tc); compareToGolden(tc.name,png,goldenPath(tc)).ok?ok++:fails.push("pixel mismatch"); }
      catch(e){ fails.push(e.message.slice(0,400)); } }
  }));
  console.log(`${ok}/${total} passed`);
  fails.slice(0,2).forEach(f=>console.log("---\n"+f));
  await closeBrowser();
})();
EOF
