    "Children's Shows": "#27ae60",
    Events: "#e67e22",
    Exhibitions: "#2c3e50",
  };
  return map[genre] || "#141414";
}


/* Does a show carry any of the selected subgenres? */
function matchesSubgenres(show) {
  return (show.subgenres || []).some((s) => state.selectedSubgenres.has(s));
}

