// Hammer one case and report what the page logged when it came up empty.
const path=require("node:path");
const R="/home/user/EdFringeNow/product/requirements";
const {newPage,ORIGIN,closeBrowser,launchBrowser}=require(path.join(R,"shared/harness/browser"));
const H=require(path.join(R,"shared/case-helpers"));
async function one(){
  const {page,context}=await newPage({localStorage:H.nowStorage()});
  const logs=[];
  page.on("console",m=>{ if(m.type()==="error"||m.type()==="warning"||/show data|cache/i.test(m.text())) logs.push(m.type()+": "+m.text().slice(0,160)); });
  page.on("pageerror",e=>logs.push("pageerror: "+e.message.slice(0,160)));
  await page.goto(`${ORIGIN}/`,{waitUntil:"load"});
  try{ await H.nowReady(page); }catch(e){ logs.push("nowReady threw: "+e.message.split("\n")[0]); }
  const cards=await page.locator(".show-item").count();
  await context.close();
  return {cards,logs};
}
(async()=>{
  await launchBrowser();
  const out=await Promise.all(Array.from({length:16},()=>one()));
  const empty=out.filter(o=>o.cards===0);
  console.log(`empty: ${empty.length}/16`);
  empty.slice(0,3).forEach((o,i)=>console.log(`--- empty run ${i}:\n   `+(o.logs.join("\n   ")||"(nothing logged)")));
  const ok=out.find(o=>o.cards>0);
  if(ok) console.log("--- a good run logged:\n   "+(ok.logs.join("\n   ")||"(nothing)"));
  await closeBrowser();
})();
EOF
