// Is Cache Storage isolated between two browser contexts on the same origin?
const path=require("node:path");
const R="/home/user/EdFringeNow/product/requirements";
const {newPage,ORIGIN,closeBrowser}=require(path.join(R,"shared/harness/browser"));
(async()=>{
  const a=await newPage({}); const b=await newPage({});
  await a.page.goto(`${ORIGIN}/`,{waitUntil:"load"});
  await b.page.goto(`${ORIGIN}/`,{waitUntil:"load"});
  await a.page.evaluate(async()=>{ const c=await caches.open("probe"); await c.put("/probe-key", new Response("from-A")); });
  const seenByB=await b.page.evaluate(async()=>{ const names=await caches.keys(); const c=await caches.open("probe"); const r=await c.match("/probe-key"); return {names, body: r? await r.text(): null}; });
  const lsA=await a.page.evaluate(()=>{ localStorage.setItem("probe","A"); return localStorage.getItem("probe"); });
  const lsB=await b.page.evaluate(()=>localStorage.getItem("probe"));
  console.log("context B sees cache names:", JSON.stringify(seenByB.names), "probe body:", JSON.stringify(seenByB.body));
  console.log("localStorage A:", lsA, " B:", JSON.stringify(lsB));
  console.log(seenByB.body==="from-A" ? "=> Cache Storage is SHARED across contexts" : "=> Cache Storage is isolated per context");
  await a.context.close(); await b.context.close(); await closeBrowser();
})();
EOF
